// Profil de composition du produit, déduit du nom du dossier.
//
// Chez Lil'OG tout ce qui se PORTE (vêtements, bijoux, accessoires) est shooté sur mannequin :
// le cadrage est déjà standardisé, on garde donc la photo en plein cadre et on ne remplace
// que le fond. Seuls les produits POSÉS à plat (sacs, chaussures) sont remis à l'échelle
// et recentrés sur le template.
const cfg = $('Config').first().json;
const dossier = $input.first().json; // le dossier en cours de traitement (id + name)
const nom = String(dossier.name || '');

// occupation : part du template occupée par le produit (1 = plein cadre / mannequin)
// ancrage    : 'centre' | 'bas'
// space      : Space de détourage spécifique à la typologie ('' = DETOURAGE_SPACE_URL)
const PROFILS = {
  vetement:   { occupation: 1.00, ancrage: 'centre', space: '' }, // mannequin
  bijou:      { occupation: 1.00, ancrage: 'centre', space: '' }, // mannequin
  accessoire: { occupation: 1.00, ancrage: 'centre', space: '' }, // mannequin
  sac:        { occupation: 0.82, ancrage: 'centre', space: '' }, // posé à plat
  chaussure:  { occupation: 0.78, ancrage: 'centre', space: '' }, // posé à plat
  defaut:     { occupation: 1.00, ancrage: 'centre', space: '' },
};

// Occupation appliquée quand un dossier est marqué [pose] sans typologie reconnue.
const OCCUPATION_POSE = 0.80;

// Mots-clés cherchés dans le nom du dossier (sans accents, mot entier).
// L'ordre compte : les typologies les plus spécifiques passent avant "vetement".
const MOTS = {
  accessoire: ['ceinture', 'lunettes', 'casquette', 'bob', 'echarpe', 'foulard', 'gant', 'gants',
               'chapeau', 'cravate', 'barrette', 'chouchou', 'porte-cles', 'montre', 'bandana',
               'mitaine', 'mitaines', 'eventail'],
  bijou: ['bijou', 'bijoux', 'collier', 'pendentif', 'bague', 'bracelet', 'boucle', 'boucles',
          'anneau', 'broche', 'piercing', 'ras-de-cou', 'choker'],
  chaussure: ['chaussure', 'chaussures', 'basket', 'baskets', 'sneaker', 'sneakers', 'botte',
              'bottes', 'bottine', 'bottines', 'sandale', 'sandales', 'mule', 'mules',
              'escarpin', 'escarpins', 'talon', 'talons', 'tong', 'tongs', 'ballerine'],
  sac: ['sac', 'sacs', 'sacoche', 'pochette', 'cabas', 'bandouliere', 'besace', 'tote',
        'portefeuille', 'porte-monnaie', 'trousse'],
  vetement: ['robe', 'top', 'debardeur', 'tshirt', 't-shirt', 'chemise', 'chemisier', 'pull',
             'gilet', 'veste', 'blouson', 'manteau', 'pantalon', 'jean', 'jeans', 'jupe', 'short',
             'combinaison', 'body', 'corset', 'bustier', 'sweat', 'hoodie', 'cardigan', 'legging',
             'jogging', 'maillot', 'crop', 'brassiere', 'kimono', 'salopette'],
};

const sansAccents = (t) => String(t).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const nomNorm = sansAccents(nom);

// 1) tag explicite dans le nom du dossier, prioritaire sur tout le reste :
//    "[sac]" / "[chaussure]" / "[bijou]"... force la typologie
//    "[pose]"      force le traitement "produit posé" (mise à l'échelle + recentrage)
//    "[mannequin]" force le plein cadre
let typologie = null;
let forcage = null;
const tag = nomNorm.match(/\[([a-z]+)\]/);
if (tag) {
  if (PROFILS[tag[1]]) typologie = tag[1];
  else if (tag[1] === 'pose' || tag[1] === 'posee') forcage = 'pose';
  else if (tag[1] === 'mannequin') forcage = 'mannequin';
}

// 2) sinon, détection par mot-clé
if (!typologie) {
  for (const [type, mots] of Object.entries(MOTS)) {
    if (mots.some((m) => new RegExp('(^|[^a-z0-9])' + m + '([^a-z0-9]|$)').test(nomNorm))) {
      typologie = type;
      break;
    }
  }
}
if (!typologie) typologie = 'defaut';

const profil = { ...PROFILS.defaut, ...(PROFILS[typologie] || {}) };

let occupation = Number(profil.occupation) || 1;
if (forcage === 'pose') occupation = OCCUPATION_POSE;
if (forcage === 'mannequin') occupation = 1;
// Secours : MODE_COMPOSITION = 'cadre' force le plein cadre pour TOUS les produits.
if (String(cfg.MODE_COMPOSITION || 'auto').toLowerCase() === 'cadre') occupation = 1;

// Dimensions réelles du template, mesurées sur l'image elle-même (le fichier fait foi).
// TEMPLATE_LARGEUR / TEMPLATE_HAUTEUR de Config ne servent que de secours.
let largeurFond = Number(cfg.TEMPLATE_LARGEUR) || 1080;
let hauteurFond = Number(cfg.TEMPLATE_HAUTEUR) || 1350;
try {
  const mesure = $('Mesurer le fond').first().json;
  const w = Number(mesure?.size?.width ?? mesure?.width);
  const h = Number(mesure?.size?.height ?? mesure?.height);
  if (w > 0 && h > 0) {
    largeurFond = w;
    hauteurFond = h;
  }
} catch (e) {
  // le nœud n'a pas tourné : on garde les valeurs de Config
}

return [{
  json: {
    ...dossier, // id et name du dossier : la suite du workflow s'en sert
    typologie,
    pose: occupation < 1,
    occupation,
    ancrage: profil.ancrage || 'centre',
    largeurFond,
    hauteurFond,
    // boîte dans laquelle le produit doit tenir, au ratio du template
    largeurProduitMax: Math.round(largeurFond * occupation),
    hauteurProduitMax: Math.round(hauteurFond * occupation),
    spaceUrl: String(profil.space || cfg.DETOURAGE_SPACE_URL || '').replace(/\/+$/, ''),
    spaceFn: String(cfg.DETOURAGE_FN || 'remove_background').replace(/^\//, ''),
  },
}];

// Trie les images du dossier courant et désigne la photo principale.
const folder = $('Boucle dossiers').first().json;

const slug = String(folder.name || 'produit')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '') || 'produit';

let images = $input.all()
  .filter((i) => typeof i.json.mimeType === 'string' && i.json.mimeType.startsWith('image/'))
  .sort((a, b) => String(a.json.name).localeCompare(String(b.json.name), 'fr', { numeric: true }));

// Si le dossier contient encore des originaux (jpg, png...), on ignore les .webp :
// ce sont les images que ce workflow a déjà produites, il ne faut pas les retraiter.
const originaux = images.filter((i) => i.json.mimeType !== 'image/webp');
if (originaux.length > 0) images = originaux;

// Dossier vide : on renvoie un marqueur, le dossier sera ignoré (pas de renommage).
if (images.length === 0) {
  return [{ json: { empty: true, folderId: folder.id, folderName: folder.name } }];
}

// Photo principale : nom contenant main / principale / cover / 1, sinon la première.
const MAIN_RE = /(^|[\s_.-])(main|principale?|cover|couverture|0?1)([\s_.-]|$)/i;
let mainIndex = images.findIndex((i) => MAIN_RE.test(String(i.json.name).replace(/\.[^.]+$/, '')));
if (mainIndex === -1) mainIndex = 0;

// La principale passe en tête : elle est donc toujours l'item [0] de ce nœud.
const ordered = [images[mainIndex], ...images.filter((_, idx) => idx !== mainIndex)];

return ordered.map((img, idx) => ({
  json: {
    id: img.json.id,
    name: img.json.name,
    mimeType: img.json.mimeType,
    isMain: idx === 0,
    position: idx + 1,
    // 1.webp, 2.webp... la photo principale est toujours la n°1.
    // Pour repasser à un nom porteur du produit : `${slug}-${String(idx + 1).padStart(2, '0')}.webp`
    newName: `${idx + 1}.webp`,
    folderId: folder.id,
    folderName: folder.name,
    empty: false,
  },
}));

// Normalise la sortie du détourage (Space Gradio, ou toute API renvoyant image / masque).
// Trois cas possibles :
//   1. une image binaire  -> produit déjà détouré
//   2. du JSON [{ label, score, mask }] -> masque base64 à poser en couche alpha
//   3. une erreur / une réponse inattendue -> mode dégradé : on garde la photo d'origine
//      et le dossier sera marqué avec le préfixe d'alerte pour relecture humaine.
const items = $input.all();
const original = $('Télécharger la photo principale').first().binary.data;

const isImage = (b) => b && String(b.mimeType || '').startsWith('image/');
const degrade = (raison) => [{
  json: { hfMode: 'echec', avertissement: true, raison: String(raison).slice(0, 300) },
  binary: { data: original },
}];

// --- Cas 1 : image détourée renvoyée directement
for (const it of items) {
  const img = Object.values(it.binary || {}).find(isImage);
  if (img) return [{ json: { hfMode: 'cutout', avertissement: false }, binary: { data: img } }];
}

// --- Cas 2 : réponse JSON (un item par entrée du tableau renvoyé par HF)
const rows = [];
for (let idx = 0; idx < items.length; idx++) {
  let j = items[idx].json;
  const keys = Object.keys(items[idx].binary || {});
  if ((!j || Object.keys(j).length === 0) && keys.length) {
    try {
      const buf = await this.helpers.getBinaryDataBuffer(idx, keys[0]);
      j = JSON.parse(buf.toString('utf8'));
    } catch (e) {
      // ignoré : traité comme réponse inattendue plus bas
    }
  }
  if (Array.isArray(j)) rows.push(...j);
  else if (j) rows.push(j);
}

const erreur = rows.find((r) => r && r.error);
if (erreur) return degrade('Détourage : ' + JSON.stringify(erreur.error));

const masques = rows
  .filter((r) => r && typeof r.mask === 'string' && r.mask.length > 100)
  .sort((a, b) => (b.score ?? 0) - (a.score ?? 0));

const choisi = masques.find((r) => !/back(ground)?|bg|fond/i.test(String(r.label || ''))) || masques[0];
if (!choisi) return degrade('Réponse inattendue (ni image, ni masque) : ' + JSON.stringify(rows));

const masque = await this.helpers.prepareBinaryData(
  Buffer.from(choisi.mask, 'base64'),
  'masque.png',
  'image/png',
);

// data = photo d'origine, mask = masque alpha -> le nœud suivant fait le détourage
return [{
  json: { hfMode: 'mask', avertissement: false, label: choisi.label ?? null },
  binary: { data: original, mask: masque },
}];

// Réunit dans un seul item le fond (template) + le produit détouré, et calcule sa position.
const profil = $('Détecter la typologie').first().json;

const produit = $('Redimensionner le produit').first().binary.data;
const fond = $('Télécharger le template de fond').first().binary.background;

const info = $('Mesurer le produit').first().json;
const largeurProduit = Number(info?.size?.width ?? info?.width ?? 0);
const hauteurProduit = Number(info?.size?.height ?? info?.height ?? 0);

// dimensions réelles du template, mesurées en début d'exécution
const largeurFond = Number(profil.largeurFond) || 1080;
const hauteurFond = Number(profil.hauteurFond) || 1350;

const posX = Math.max(0, Math.round((largeurFond - largeurProduit) / 2));

// 'bas' : le produit repose sur une marge basse de 6 % (non utilisé par défaut,
// sacs et chaussures sont centrés comme sur la boutique).
const margeBasse = Math.round(hauteurFond * 0.06);
const posY = profil.ancrage === 'bas'
  ? Math.max(0, hauteurFond - hauteurProduit - margeBasse)
  : Math.max(0, Math.round((hauteurFond - hauteurProduit) / 2));

return [{
  json: {
    posX,
    posY,
    typologie: profil.typologie,
    pose: profil.pose,
    occupation: profil.occupation,
    largeurProduit,
    hauteurProduit,
    largeurFond,
    hauteurFond,
  },
  binary: { data: fond, cutout: produit },
}];

// Récapitulatif des dossiers validés pendant cette exécution.
const dossiers = $input.all()
  .filter((i) => i.json && i.json.name && i.json.empty !== true)
  .map((i) => i.json.name);

return [{
  json: {
    event: 'lilog_images_ready',
    prefix: $('Config').first().json.PREFIXE_TRAITE,
    foldersProcessed: dossiers.length,
    folders: dossiers,
    finishedAt: new Date().toISOString(),
  },
}];
